interface GenerationTaskRuntimeTransition {
  expectedRevision: number;
  transition: MeetingTaskRuntimeTransitionKind;
  reason: string;
  parent?: ActiveInterviewParent | null;
  screenAttachment?: ActiveScreenTask | null;
}

interface PendingGenerationAnswerRevision extends PendingAnswerRevision {
  unpublishedArtifacts?: UnpublishedArtifactOffer;
  childSummary?: string;
  deadlineDelta?: MeetingTaskDeadlineDelta;
  deadlineCalculatedAt?: number;
  resultTaskId: string | null;
  taskRuntimeRevision: number;
  taskRuntimeTransition?: GenerationTaskRuntimeTransition;
}

function resolveStableAnswerSectionOwner(input: {
  activeMeetingTask?: ActiveMeetingTask;
  artifactRegenerationTarget?: Pick<
    ArtifactRegenerationTarget,
    "sectionOwner"
  >;
}): EffectiveQuestionSourceOwner | null {
  if (input.artifactRegenerationTarget) {
    return { ...input.artifactRegenerationTarget.sectionOwner };
  }
  const task = input.activeMeetingTask;
  if (!task) return null;
  if (task.child) {
    return {
      kind: "active-child",
      parentId: task.parent.id,
      childId: task.child.id,
    };
  }
  return { kind: "parent-mainline", parentId: task.parent.id };
}

interface PreparedStableAnswerPublication {
  stable: StableAnswerRevision;
  selectedQuestionOnly: boolean;
  options: {
    unpublishedArtifacts?: UnpublishedArtifactOffer;
    clearPrevious?: boolean;
    pendingDisposition?: string;
    latestUsefulAnswerCommitted?: boolean;
    latestUsefulAnswerChars?: number;
    artifactOnly?: boolean;
    deadlineDelta?: MeetingTaskDeadlineDelta;
    childSummary?: string;
    deadlineCalculatedAt?: number;
    presentationParent?: ActiveInterviewParent | null;
  };
  previousGeneratedContinuity: BoundedGeneratedContinuityState;
  nextGeneratedContinuity: BoundedGeneratedContinuityState;
  deadlineUpdate?: PreparedMeetingTaskDeadlineUpdate;
  pending: PendingAnswerRevision | null;
  previousStable: StableAnswerRevision | null;
  previousVisibleAnswerRevision: number;
  previousManualCorrectionTargetHistory: ManualCorrectionRuntimeTarget[];
  nextManualCorrectionTargetHistory: ManualCorrectionRuntimeTarget[];
  previousLatestManualCorrectionTarget?: ManualCorrectionRuntimeTarget;
  nextLatestManualCorrectionTarget?: ManualCorrectionRuntimeTarget;
  previousPendingAnswerRevision: PendingGenerationAnswerRevision | null;
  previousAnswerDeliveryProgress: AnswerDeliveryProgress | null;
}

function prepareGenerationDerivedTaskRuntimeTransition(input: {
  currentRevision: number;
  currentParent?: ActiveInterviewParent;
  transition?: GenerationTaskRuntimeTransition;
  stable: StableAnswerRevision;
  commitLatestUsefulAnswer: boolean;
}): {
  transition?: GenerationTaskRuntimeTransition;
  latestUsefulAnswerCommitted: boolean;
  latestUsefulAnswerChars: number;
} {
  if (!input.commitLatestUsefulAnswer) {
    return {
      transition: input.transition
        ? {
            ...input.transition,
            expectedRevision: input.currentRevision,
          }
        : undefined,
      latestUsefulAnswerCommitted: false,
      latestUsefulAnswerChars: 0,
    };
  }

  const summary = input.stable.suggestion.meetingAnswer
    ? buildMeetingAnswerSummary(
        input.stable.suggestion.meetingAnswer
      ).text.trim()
    : "";
  const parent = input.transition && input.transition.parent !== undefined
    ? input.transition?.parent ?? undefined
    : input.currentParent;
  const summaryAuthorized = Boolean(parent && parent.id === input.stable.taskId && summary);
  return {
    transition: input.transition
      ? {
          ...input.transition,
          expectedRevision: input.currentRevision,
        }
      : undefined,
    latestUsefulAnswerCommitted: summaryAuthorized,
    latestUsefulAnswerChars: summaryAuthorized ? summary.length : 0,
  };
}

// Task 178A. The sole task writer's own result, handed to a read-only observer
// right after the writer returned. It cannot change or veto that result.
type TaskRuntimeWriterObserver = (
  result: {
    authorized: boolean;
    mutationApplied: boolean;
    reason: string;
    state: {
      revision: number;
      parent?: { id: string };
      lastMutation?: { id: string; appliedAt: number };
    };
  },
  mutation: { id?: string; transition: string }
) => void;

function submitTaskRuntimeTransition(
  manager: MeetingContextManager,
  input: {
    operationId?: string;
    transition: MeetingTaskRuntimeTransitionKind;
    authorizedArtifacts?: readonly AnswerArtifactSection[];
    deadlineDelta?: MeetingTaskDeadlineDelta;
    reason: string;
    parent?: ActiveInterviewParent | null;
    screenAttachment?: ActiveScreenTask | null;
    expectedRevision?: number;
    recentParentToRestore?: string;
    sourceOwnerCorrection?: ReturnType<EffectiveQuestionSourceLedger["prepareOwnerCorrection"]>;
  },
  observeWriter?: TaskRuntimeWriterObserver
) {
  const { operationId, ...transition } = input;
  const mutationId = operationId ?? createMeetingId("task_runtime_transition");
  const result = manager.commitTaskRuntimeTransition({
    id: mutationId,
    expectedRevision:
      input.expectedRevision ?? manager.getTaskRuntimeState().revision,
    ...transition,
  });
  if (!result.authorized) {
    console.warn("Meeting task runtime transition rejected", {
      transition: input.transition,
      reason: input.reason,
      rejectionReason: result.reason,
    });
  }
  observeWriter?.(result, { id: mutationId, transition: input.transition });
  return result;
}

function commitSourceOwnedTransitionWithManager(input: {
  manager: MeetingContextManager;
  candidate: NonNullable<
    ReturnType<typeof createSourceOwnedTransitionCandidate>
  >;
  expectedTaskRuntimeRevision: number;
  currentSessionId: string;
  currentRuntimeEpoch: number;
  operationId?: string;
  reason: string;
  observeWriter?: TaskRuntimeWriterObserver;
}): SourceOwnedDurableTransitionReceipt {
  const runtimeBefore = input.manager.getTaskRuntimeState();
  return commitSourceOwnedTransitionToRuntime({
    candidate: input.candidate,
    runtimeBefore,
    expectedTaskRuntimeRevision: input.expectedTaskRuntimeRevision,
    currentSessionId: input.currentSessionId,
    currentRuntimeEpoch: input.currentRuntimeEpoch,
    commitRuntime: ({
      sourceResult,
      runtimeBefore: committedRuntimeBefore,
      expectedTaskRuntimeRevision,
    }) => {
      const runtimeTransition = resolveSourceOwnedRuntimeTransition({
        sourceResult,
        runtimeBefore: committedRuntimeBefore,
      });
      const runtimeResult = submitTaskRuntimeTransition(input.manager, {
        operationId: input.operationId ?? sourceResult.candidate.id,
        transition: runtimeTransition,
        reason: input.reason,
        expectedRevision: expectedTaskRuntimeRevision,
        deadlineDelta: sourceResult.task && sourceResult.mutationApplied
          ? { parent: { ownerId: sourceResult.task.id, deadline: sourceResult.candidate.expiresAt } }
          : undefined,
        screenAttachment:
          sourceResult.candidate.kind === "new-parent" ||
          sourceResult.candidate.kind === "reseed-parent"
            ? null
            : committedRuntimeBefore.screenAttachment,
        parent: sourceResult.task ?? null,
      }, input.observeWriter);
      return { runtimeResult, runtimeTransition };
    },
  });
}

function commitPlannedTaskRuntimeTransition(input: {
  manager: MeetingContextManager;
  planInput: Omit<Parameters<typeof buildSettledAdvisorExecutionPlan>[0], "activeMeetingTask" | "expectedActiveMeetingTask"> & {
    explicitTaskMutationCommand: Exclude<TaskLifecycleCommand, { kind: "preserve" }>;
  };
  currentContext: MeetingContextState;
  currentLogicalQuestionUnit: LogicalQuestionUnit;
  currentRuntimeEpoch?: number;
  recentParentToRestore?: string;
  sourceOwnerCorrection?: ReturnType<EffectiveQuestionSourceLedger["prepareOwnerCorrection"]>;
  parentAfter: ActiveInterviewParent;
  screenAfter?: ActiveScreenTask | null;
  deadlineDelta?: MeetingTaskDeadlineDelta;
  operationId: string;
  observeWriter?: TaskRuntimeWriterObserver;
}) {
  const before = input.currentContext.taskRuntime;
  const runtimeTransition = input.planInput.explicitTaskMutationCommand.kind;
  const prepared = input.manager.prepareTaskRuntimeTransition({
    id: input.operationId, transition: runtimeTransition,
    command: input.planInput.explicitTaskMutationCommand,
    reason: "correction-lifecycle-command-committed",
    expectedRevision: before.revision,
    parent: input.parentAfter, screenAttachment: input.screenAfter,
    deadlineDelta: input.deadlineDelta,
    recentParentToRestore: input.recentParentToRestore,
    sourceOwnerCorrection: input.sourceOwnerCorrection,
  });
  const projectedTask = projectActiveMeetingTask({ state: prepared.result.state });
  const plan = buildSettledAdvisorExecutionPlan({
    ...input.planInput,
    activeMeetingTask: projectedTask,
    expectedActiveMeetingTask: input.currentContext.activeMeetingTask ?? null,
  });
  const authorizationInput = {
    plan, currentSettlement: input.planInput.settlement,
    currentSessionId: prepared.expectedSessionId,
    currentRuntimeEpoch: input.currentRuntimeEpoch ?? input.currentLogicalQuestionUnit.runtimeEpoch,
    currentLogicalQuestionUnitId: input.currentLogicalQuestionUnit.id,
    currentLogicalQuestionRevision: input.currentLogicalQuestionUnit.revision,
    currentSourceHash: input.planInput.settlement.sourceHash,
  };
  const preMutationAuthorization = authorizeSettledAdvisorExecutionPlan({
    ...authorizationInput, currentActiveMeetingTask: projectActiveMeetingTask({ state: prepared.previousState }),
    stage: "pre-task-mutation",
  });
  const postMutationAuthorization = authorizeSettledAdvisorExecutionPlan({
    ...authorizationInput, currentActiveMeetingTask: projectedTask,
  });
  const ready = prepared.result.authorized && prepared.result.mutationApplied &&
    preMutationAuthorization.authorized && postMutationAuthorization.authorized;
  const runtimeResult = ready
    ? input.manager.commitPreparedTaskRuntimeTransition(prepared)
    : undefined;
  if (runtimeResult) {
    input.observeWriter?.(runtimeResult, { id: input.operationId, transition: runtimeTransition });
  }
  const authorized = Boolean(runtimeResult?.authorized && runtimeResult.mutationApplied);
  const reason = !preMutationAuthorization.authorized ? `pre-mutation:${preMutationAuthorization.reason}`
    : !prepared.result.authorized || !prepared.result.mutationApplied ? prepared.result.reason
    : !postMutationAuthorization.authorized ? `post-mutation:${postMutationAuthorization.reason}`
    : !authorized ? runtimeResult?.reason ?? "canonical-runtime-transition-rejected" : "authorized";
  return {
    authorized,
    reason,
    plan, prepared, preMutationAuthorization, postMutationAuthorization, runtimeTransition, runtimeResult,
    lifecycleMetadata: formatTaskRuntimeTransitionForTrace({
      operationId: input.operationId, executionPlanId: plan.id,
      before: prepared.previousState,
      result: runtimeResult ?? { ...prepared.result, authorized: false, mutationApplied: false },
      rejectionReason: authorized ? undefined : reason,
    }),
  };
}

function prepareGenerationDerivedTaskRuntimeCommit(
  manager: MeetingContextManager,
  input: {
    operationId?: string;
    transition: MeetingTaskRuntimeTransitionKind;
    reason: string;
    parent?: ActiveInterviewParent | null;
    screenAttachment?: ActiveScreenTask | null;
    expectedRevision?: number;
  },
  authorizedArtifacts: readonly AnswerArtifactSection[] = []
) {
  const { operationId, ...transition } = input;
  const prepared = manager.prepareTaskRuntimeTransition({
    id: operationId ?? createMeetingId("task_runtime_transition"),
    expectedRevision:
      input.expectedRevision ?? manager.getTaskRuntimeState().revision,
    ...transition,
    authorizedArtifacts,
  });
  return {
    authorized: prepared.result.authorized,
    reason: prepared.result.reason,
    value: prepared,
  };
}

function submitTaskRuntimeClear(
  manager: MeetingContextManager,
  input: {
    scope: "all" | "parent" | "screen";
    reason: string;
    expectedRevision?: number;
  },
  observeWriter?: TaskRuntimeWriterObserver
) {
  const mutationId = createMeetingId("task_runtime_clear");
  const result = manager.clearTaskRuntime({
    id: mutationId,
    expectedRevision:
      input.expectedRevision ?? manager.getTaskRuntimeState().revision,
    ...input,
  });
  if (!result.authorized) {
    console.warn("Meeting task runtime clear rejected", {
      scope: input.scope,
      reason: input.reason,
      rejectionReason: result.reason,
    });
  }
  observeWriter?.(result, { id: mutationId, transition: `clear-${input.scope}` });
  return result;
}

function mapSourceOwnedExecutionPlanCommand(
  receipt: SourceOwnedDurableTransitionReceipt | undefined
): TaskLifecycleCommand | undefined {
  if (!sourceOwnedTransitionDurableMutationApplied(receipt)) {
    return undefined;
  }

  const result = receipt!.sourceResult;
  const candidate = result.candidate;
  if (receipt?.runtimeTransition === "update-parent-context") return { kind: "update-parent-context" };
  if (candidate.kind === "new-parent") {
    return {
      kind: "create-parent",
      type: candidate.questionType,
      topic: candidate.question || "Unknown interview task",
    };
  }
  if (candidate.kind === "reseed-parent") {
    return {
      kind: "replace-parent",
      type: candidate.questionType,
      topic: candidate.question || "Unknown interview task",
    };
  }
  if (candidate.kind === "child-probe") {
    return {
      kind: "attach-child",
      type: candidate.questionType,
      question: candidate.question || "Unknown child question",
    };
  }
  if (candidate.kind === "resume-parent") {
    return { kind: "resume-parent" };
  }
  if (candidate.kind === "phase-progress" && result.task) {
    return result.phaseBefore !== result.phaseAfter
      ? {
          kind: "set-phase",
          owner: {
            kind: "parent",
            id: result.task.id,
          },
          phase: result.task.playbookPhase,
        }
      : { kind: "update-parent-context" };
  }
  return undefined;
}

function classifyCommittedTaskRuntimeTransition(input: {
  beforeParent?: ActiveInterviewParent;
  afterParent?: ActiveInterviewParent;
  beforeScreen?: ActiveScreenTask;
  afterScreen?: ActiveScreenTask;
}): MeetingTaskRuntimeTransitionKind | undefined {
  const { beforeParent, afterParent, beforeScreen, afterScreen } = input;
  if (beforeParent === afterParent && beforeScreen === afterScreen) {
    return undefined;
  }
  if (!beforeParent && afterParent) return "create-parent";
  if (beforeParent && afterParent) {
    if (
      beforeParent.id !== afterParent.id ||
      beforeParent.stableKind !== afterParent.stableKind
    ) {
      return "replace-parent";
    }
    if (!beforeParent.child && afterParent.child) return "attach-child";
    if (beforeParent.child && !afterParent.child) return "resume-parent";
    if (beforeParent.playbookPhase !== afterParent.playbookPhase) {
      return "set-phase";
    }
  }
  if (beforeScreen !== afterScreen) return "update-source-attachment";
  if (beforeParent && afterParent) return "update-parent-context";
  return undefined;
}

